import java.util.*;public class Solution102 { static class Pair{    TreeNode node;    int level;    public Pair(TreeNode node, int level) {        this.node = node;        this.level = level;    }}    public static List<List<Integer>> levelOrder(TreeNode root) {        Queue<Pair> que1 = new LinkedList<>();        List<List<Integer>> ans = new ArrayList<>();        List<Integer> temp = new ArrayList<>();        int currentLevel = 0;        que1.add(new Pair(root,0));        if(root == null) return ans;        while (!que1.isEmpty()){            Pair front = que1.remove();            TreeNode n1 = front.node;            int level = front.level;            if(currentLevel!=level){                currentLevel++;                ans.add(temp);                temp = new ArrayList<>();            }            temp.add(n1.val);            if(n1.left!=null){                que1.add(new Pair(n1.left,level+1));            }            if(n1.right!=null){                que1.add(new Pair(n1.right,level+1));            }        }        if(!temp.isEmpty()) ans.add(temp);        return ans;    }    /** or can do this code (but takes 4ms)    class Solution {        public List<List<Integer>> levelOrder(TreeNode root) {            List<List<Integer>> ans = new ArrayList<>();            List<Integer> al1 = new ArrayList<>();            int height1 = height(root);            for(int i = 0; i<=height1; i++){                kthLevelElements(root,0,i);                ans.add(temp);                temp = new ArrayList<>();            }            return ans;        }        ArrayList<Integer> temp = new ArrayList<>();        void kthLevelElements(TreeNode root, int level, int k){            if(root==null) return;            if(level==k) temp.add(root.val);            kthLevelElements(root.left,level+1,k);            kthLevelElements(root.right,level+1,k);        }        int height(TreeNode node) {            if (node == null) {                return -1; // for empty tree, height is -1            }            int leftHeight = height(node.left);            int rightHeight = height(node.right);            return Math.max(leftHeight, rightHeight) + 1;        }    }     */}